sidebarCSS:
#root.root {--tabs-activated-bg: #ff8f36ff;}



#root.root .Tab[data-pin="true"] [class*="badge"] {
  background: #ecb22e !important;
}

/* P1: title has count */
#root.root .Tab[data-pin="true"][data-title*="("] [class*="badge"] {
  background: #e01e5a !important;
}

.Tab[data-discarded] .fav,
.Tab[data-discarded] .fav svg {
  opacity: 1 !important;
}


.Tab .exp svg {
  stroke: red;
}
